<?php
$page_title = 'Procurement & Purchases';
require_once __DIR__ . '/../../includes/header.php';
/** @var mysqli $conn */
$conn = getDatabaseConnection();

$permissions = require __DIR__ . '/permissions.php';
$businessId = (int)($_SESSION['active_business_id'] ?? 0);
$membershipId = (int)($_SESSION['membership_id'] ?? 0);
requirePermission($conn, $membershipId, $businessId, $permissions['view']);

$canCreatePurchase = hasPermission($conn, $membershipId, $businessId, $permissions['create']);
$canUpdatePurchase = hasPermission($conn, $membershipId, $businessId, $permissions['update']);
$canDeletePurchase = hasPermission($conn, $membershipId, $businessId, $permissions['delete']);
$canReceivePurchase = hasPermission($conn, $membershipId, $businessId, $permissions['receive']);
$config = getBusinessInventoryConfig($conn, $businessId);
$localNow = new DateTimeImmutable('now', new DateTimeZone($config['timezone']));
$roleQuery = getRolePreviewQuery();
$csrfToken = generateCsrfToken();

$businessStmt = mysqli_prepare($conn, 'SELECT currency_code,business_name FROM businesses WHERE id=? LIMIT 1');
mysqli_stmt_bind_param($businessStmt, 'i', $businessId);
mysqli_stmt_execute($businessStmt);
$businessInfo = mysqli_fetch_assoc(mysqli_stmt_get_result($businessStmt)) ?: [];
$currency = $businessInfo['currency_code'] ?? 'RWF';

$search = trim((string)($_GET['search'] ?? ''));
$statusFilter = strtoupper(trim((string)($_GET['status'] ?? '')));
$validStatuses = ['DRAFT','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED'];
if (!in_array($statusFilter, $validStatuses, true)) $statusFilter = '';
$typeFilter = strtoupper(trim((string)($_GET['type'] ?? '')));
$validTypes = ['DIRECT','PURCHASE_ORDER'];
if (!in_array($typeFilter, $validTypes, true)) $typeFilter = '';
$page = max(1, (int)($_GET['page'] ?? 1));
$limit = 20;
$offset = ($page - 1) * $limit;

$where = ' WHERE p.business_id=?';
$params = [$businessId];
$types = 'i';
if ($search !== '') {
    $where .= ' AND (p.purchase_number LIKE ? OR s.name LIKE ? OR COALESCE(p.supplier_invoice_number,\'\') LIKE ?)';
    $searchLike = '%' . $search . '%';
    array_push($params,$searchLike,$searchLike,$searchLike);
    $types .= 'sss';
}
if ($statusFilter !== '') {
    $where .= ' AND p.status=?';
    $params[] = $statusFilter;
    $types .= 's';
}
if ($typeFilter !== '') {
    $where .= ' AND p.purchase_type=?';
    $params[] = $typeFilter;
    $types .= 's';
}

$countStmt = mysqli_prepare($conn, "SELECT COUNT(*) total FROM purchases p JOIN suppliers s ON s.id=p.supplier_id AND s.business_id=p.business_id $where");
mysqli_stmt_bind_param($countStmt, $types, ...$params);
mysqli_stmt_execute($countStmt);
$totalRows = (int)(mysqli_fetch_assoc(mysqli_stmt_get_result($countStmt))['total'] ?? 0);
$totalPages = (int)ceil($totalRows/$limit);

$listStmt = mysqli_prepare($conn, "SELECT p.id,p.purchase_number,p.purchase_type,p.supplier_invoice_number,p.status,p.purchase_date,p.received_at,p.total_amount,p.amount_paid,p.payment_status,p.notes,
        s.name supplier_name,l.name location_name,l.code location_code,COUNT(pi.id) line_count,
        COALESCE(SUM(pi.received_quantity*pi.unit_cost),0) received_value,
        COALESCE(SUM((pi.ordered_quantity-pi.received_quantity)*pi.unit_cost),0) remaining_value
    FROM purchases p
    JOIN suppliers s ON s.id=p.supplier_id AND s.business_id=p.business_id
    JOIN business_locations l ON l.id=p.location_id AND l.business_id=p.business_id
    LEFT JOIN purchase_items pi ON pi.purchase_id=p.id AND pi.business_id=p.business_id
    $where
    GROUP BY p.id,p.purchase_number,p.purchase_type,p.supplier_invoice_number,p.status,p.purchase_date,p.received_at,p.total_amount,p.amount_paid,p.payment_status,p.notes,s.name,l.name,l.code
    ORDER BY p.purchase_date DESC,p.id DESC LIMIT ? OFFSET ?");
$listParams = array_merge($params,[$limit,$offset]);
$listTypes = $types . 'ii';
mysqli_stmt_bind_param($listStmt,$listTypes,...$listParams);
mysqli_stmt_execute($listStmt);
$purchases = mysqli_stmt_get_result($listStmt);

$summaryStmt = mysqli_prepare($conn, "SELECT COUNT(*) total_purchases,SUM(purchase_type='DIRECT') direct_purchases,SUM(purchase_type='PURCHASE_ORDER') purchase_orders,SUM(status IN ('DRAFT','ORDERED','PARTIALLY_RECEIVED')) open_purchases,SUM(status='RECEIVED') received_purchases,COALESCE(SUM(total_amount),0) total_value FROM purchases WHERE business_id=?");
mysqli_stmt_bind_param($summaryStmt,'i',$businessId);
mysqli_stmt_execute($summaryStmt);
$summary = mysqli_fetch_assoc(mysqli_stmt_get_result($summaryStmt)) ?: [];

$supplierStmt = mysqli_prepare($conn,'SELECT id,name FROM suppliers WHERE business_id=? AND is_active=1 ORDER BY name');
mysqli_stmt_bind_param($supplierStmt,'i',$businessId);mysqli_stmt_execute($supplierStmt);
$suppliers=[];$supplierResult=mysqli_stmt_get_result($supplierStmt);while($row=mysqli_fetch_assoc($supplierResult))$suppliers[]=$row;
$locationStmt = mysqli_prepare($conn,'SELECT id,name,code FROM business_locations WHERE business_id=? AND is_active=1 ORDER BY name');
mysqli_stmt_bind_param($locationStmt,'i',$businessId);mysqli_stmt_execute($locationStmt);
$locations=[];$locationResult=mysqli_stmt_get_result($locationStmt);while($row=mysqli_fetch_assoc($locationResult))$locations[]=$row;
$productStmt = mysqli_prepare($conn,'SELECT id,name,sku,uom,track_batches,track_expiry FROM products WHERE business_id=? AND is_active=1 ORDER BY name');
mysqli_stmt_bind_param($productStmt,'i',$businessId);mysqli_stmt_execute($productStmt);
$productOptions=[];$productResult=mysqli_stmt_get_result($productStmt);while($row=mysqli_fetch_assoc($productResult))$productOptions[]=$row;

$statusMeta = static function(string $status): array {
    return match($status) {
        'RECEIVED' => ['Fully Received','pill-green'],
        'PARTIALLY_RECEIVED' => ['Partially Received','pill-amber'],
        'ORDERED' => ['Ordered / Pending','pill-blue'],
        'DRAFT' => ['Draft','pill-amber'],
        default => ['Cancelled','pill-red'],
    };
};
$queryBase = array_filter(['search'=>$search,'status'=>$statusFilter,'type'=>$typeFilter,'role'=>getPreviewRole()],static fn($value)=>$value!==null&&$value!=='');
$closeQuery = http_build_query($queryBase);
if ((int)($_GET['view_id'] ?? 0) > 0) {
    $legacyViewParams = array_merge($queryBase, ['id' => (int)$_GET['view_id']]);
    header('Location: view?' . http_build_query($legacyViewParams));
    exit;
}
?>

<main class="purchase-workspace">
<div class="purchase-page-head"><div><h1>Purchases</h1><p>Create direct purchases or purchase orders, then track receiving in one place.</p></div><div class="purchase-head-actions"><a class="btn-sm receiving-link" href="../receiving/index<?php echo e($roleQuery); ?>">Purchase Receiving</a><?php if($canCreatePurchase):?><a class="btn-primary purchase-create-link" href="create<?php echo e($roleQuery); ?>"><span class="purchase-create-icon" aria-hidden="true"><svg viewBox="0 0 20 20" focusable="false"><path d="M4 3h9l3 3v11H4V3Zm9 0v4h3M7 11h6M10 8v6"/></svg></span><span>Start Purchase</span></a><?php endif;?></div></div>

<div class="purchase-summary">
  <div class="card purchase-value-card"><span>Total Purchase Value</span><strong><?php echo formatCurrency($summary['total_value']??0,$currency);?></strong><small>Across all purchase methods</small></div>
  <div class="card"><span>Direct Purchases</span><strong><?php echo (int)($summary['direct_purchases']??0);?></strong><small>Immediate receiving workflow</small></div>
  <div class="card"><span>Purchase Orders</span><strong><?php echo (int)($summary['purchase_orders']??0);?></strong><small>Separate order workflow</small></div>
  <div class="card"><span>Open Purchases</span><strong><?php echo (int)($summary['open_purchases']??0);?></strong><small>Awaiting workflow completion</small></div>
  <div class="card"><span>Fully Received</span><strong><?php echo (int)($summary['received_purchases']??0);?></strong><small>Completed purchases</small></div>
</div>

<section class="card purchase-directory">
  <div class="purchase-toolbar"><div><div class="card-title">Purchase Records</div><p><?php echo number_format($totalRows);?> purchase(s) found</p></div><form method="GET" class="purchase-filter"><?php if(getPreviewRole()):?><input type="hidden" name="role" value="<?php echo e(getPreviewRole());?>"><?php endif;?><select name="type" aria-label="Filter by purchase method"><option value="">All methods</option><option value="DIRECT" <?php echo $typeFilter==='DIRECT'?'selected':'';?>>Direct Purchase</option><option value="PURCHASE_ORDER" <?php echo $typeFilter==='PURCHASE_ORDER'?'selected':'';?>>Purchase Order</option></select><select name="status" aria-label="Filter by status"><option value="">All statuses</option><?php foreach($validStatuses as $status):$meta=$statusMeta($status);?><option value="<?php echo $status;?>" <?php echo $statusFilter===$status?'selected':'';?>><?php echo e($meta[0]);?></option><?php endforeach;?></select><input type="search" name="search" value="<?php echo e($search);?>" placeholder="Search number, supplier, or invoice" aria-label="Search purchases"><button class="btn-sm">Apply Filters</button><?php if($search!==''||$statusFilter!==''||$typeFilter!==''):?><a class="btn-sm" href="index<?php echo e($roleQuery);?>">Clear Filters</a><?php endif;?></form></div>
  <div class="purchase-table-wrap table-scroll" tabindex="0" aria-label="Purchases"><table class="data-table purchase-table"><thead><tr><th>Purchase &amp; Supplier</th><th>Delivery</th><th>Value</th><th>Receiving</th><th>Status</th><th class="purchase-actions">Actions</th></tr></thead><tbody>
    <?php if(mysqli_num_rows($purchases)===0):?><tr><td colspan="6" class="purchase-empty">No purchases match the selected filters.</td></tr>
    <?php else:while($purchase=mysqli_fetch_assoc($purchases)):$meta=$statusMeta($purchase['status']);$total=(float)$purchase['total_amount'];$received=(float)$purchase['received_value'];$progress=$purchase['status']==='RECEIVED'?100:($total>0?min(100,($received/$total)*100):0);?>
      <tr><td class="purchase-order-cell"><strong><?php echo e($purchase['purchase_number']);?></strong><span class="purchase-type-badge <?php echo $purchase['purchase_type']==='DIRECT'?'type-direct':'type-order';?>"><?php echo $purchase['purchase_type']==='DIRECT'?'Direct Purchase':'Purchase Order';?></span><small><?php echo e($purchase['supplier_name']);?></small><?php if($purchase['supplier_invoice_number']):?><small>Invoice <?php echo e($purchase['supplier_invoice_number']);?></small><?php endif;?></td><td><span class="location-badge"><?php echo e($purchase['location_code']);?></span><small><?php echo e($purchase['location_name']);?> &middot; <?php echo e(formatDate($purchase['purchase_date'],$config['timezone'],'d M Y'));?></small></td><td class="order-value"><?php echo formatCurrency($purchase['total_amount'],$currency);?><small><?php echo e($purchase['payment_status']==='PAID'?'Paid':($purchase['payment_status']==='PARTIALLY_PAID'?'Partially paid':'Debt'));?> &middot; <?php echo formatCurrency(max(0,(float)$purchase['total_amount']-(float)$purchase['amount_paid']),$currency);?> due</small></td><td><div class="po-progress"><div style="width:<?php echo e(number_format($progress,2,'.',''));?>%"></div></div><small><?php echo e(number_format($progress,0));?>% received &middot; <?php echo formatCurrency($purchase['remaining_value'],$currency);?> pending</small></td><td><span class="status-pill <?php echo $meta[1];?>"><?php echo e($meta[0]);?></span></td><td class="purchase-actions"><a class="btn-sm purchase-view-action" href="view?<?php echo e(http_build_query(array_merge($queryBase,['id'=>(int)$purchase['id']])));?>">View Purchase Details</a><?php if($canUpdatePurchase||$canDeletePurchase||($purchase['status']==='DRAFT'&&$canUpdatePurchase)||(in_array($purchase['status'],['ORDERED','PARTIALLY_RECEIVED'],true)&&$canReceivePurchase)||(in_array($purchase['status'],['PARTIALLY_RECEIVED','RECEIVED'],true)&&$canReceivePurchase)):?><details class="purchase-action-menu"><summary aria-label="Purchase actions for <?php echo e($purchase['purchase_number']);?>">Purchase Actions</summary><div><?php if($canUpdatePurchase):?><a href="edit?<?php echo e(http_build_query(array_merge($queryBase,['id'=>(int)$purchase['id']])));?>#record-payment"><?php echo (float)$purchase['total_amount']-(float)$purchase['amount_paid']>0.00005?'Pay Remaining Balance':'Edit Purchase';?></a><?php endif;?><?php if($purchase['status']==='DRAFT'&&$canUpdatePurchase):?><form action="backend<?php echo e($roleQuery);?>" method="POST" onsubmit="return confirm('Mark this purchase order as ordered?');"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken);?>"><input type="hidden" name="action" value="mark_ordered"><input type="hidden" name="purchase_id" value="<?php echo (int)$purchase['id'];?>"><button>Mark as Ordered</button></form><?php elseif(in_array($purchase['status'],['ORDERED','PARTIALLY_RECEIVED'],true)&&$canReceivePurchase):?><a href="../receiving/view?id=<?php echo (int)$purchase['id'];?><?php echo getPreviewRole()?'&role='.e(getPreviewRole()):'';?>">Receive Purchase</a><?php endif;?><?php if(in_array($purchase['status'],['PARTIALLY_RECEIVED','RECEIVED'],true)&&$canReceivePurchase):?><a href="?<?php echo e(http_build_query(array_merge($queryBase,['return_id'=>(int)$purchase['id']])));?>">Return Purchased Stock</a><?php endif;?><?php if($canDeletePurchase):?><form action="backend<?php echo e($roleQuery);?>" method="POST" onsubmit="return confirm('Delete <?php echo e($purchase['purchase_number']); ?>? Received stock will be reversed. This action cannot be undone.');"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken);?>"><input type="hidden" name="action" value="delete_purchase"><input type="hidden" name="purchase_id" value="<?php echo (int)$purchase['id'];?>"><button class="purchase-delete-action">Delete Purchase</button></form><?php endif;?></div></details><?php endif;?></td></tr>
    <?php endwhile;endif;?>
  </tbody></table></div>
  <?php if($totalPages>1):?><div class="purchase-pagination"><span>Page <?php echo $page;?> of <?php echo $totalPages;?> &middot; <?php echo $totalRows;?> purchases</span><div><?php if($page>1):?><a class="btn-sm" href="?<?php echo e(http_build_query(array_merge($queryBase,['page'=>$page-1])));?>">Previous Page</a><?php endif;?><?php if($page<$totalPages):?><a class="btn-sm" href="?<?php echo e(http_build_query(array_merge($queryBase,['page'=>$page+1])));?>">Next Page</a><?php endif;?></div></div><?php endif;?>
</section>
</main>

<?php
$detailPurchase=null;$detailLines=[];$detailPayments=[];$detailReturns=[];
$viewId=(int)($_GET['view_id']??0);
if($viewId>0){
  $detailStmt=mysqli_prepare($conn,"SELECT p.*,s.supplier_code,s.name supplier_name,s.contact_person supplier_contact,s.phone supplier_phone,s.email supplier_email,s.tax_number supplier_tax_number,s.address supplier_address,s.notes supplier_notes,l.name location_name,l.code location_code,l.location_type,l.address location_address,CONCAT(cu.first_name,' ',cu.last_name) created_by,CONCAT(au.first_name,' ',au.last_name) approved_by,CONCAT(ru.first_name,' ',ru.last_name) received_by FROM purchases p JOIN suppliers s ON s.id=p.supplier_id AND s.business_id=p.business_id JOIN business_locations l ON l.id=p.location_id AND l.business_id=p.business_id LEFT JOIN business_memberships cbm ON cbm.id=p.created_by_membership_id AND cbm.business_id=p.business_id LEFT JOIN users cu ON cu.id=cbm.user_id LEFT JOIN business_memberships abm ON abm.id=p.approved_by_membership_id AND abm.business_id=p.business_id LEFT JOIN users au ON au.id=abm.user_id LEFT JOIN business_memberships rbm ON rbm.id=p.received_by_membership_id AND rbm.business_id=p.business_id LEFT JOIN users ru ON ru.id=rbm.user_id WHERE p.id=? AND p.business_id=? LIMIT 1");
  mysqli_stmt_bind_param($detailStmt,'ii',$viewId,$businessId);mysqli_stmt_execute($detailStmt);$detailPurchase=mysqli_fetch_assoc(mysqli_stmt_get_result($detailStmt));
  if($detailPurchase){
    $detailLineStmt=mysqli_prepare($conn,"SELECT pi.*,pr.name product_name,pr.sku,pr.barcode,pr.uom,tu.code purchase_uom,ppu.code package_uom,pb.lot_number,COALESCE(pi.expiry_date,pb.expires_at) expires_at,COALESCE((SELECT SUM(pri.quantity) FROM purchase_return_items pri JOIN purchase_returns prr ON prr.id=pri.purchase_return_id AND prr.business_id=pri.business_id WHERE pri.purchase_item_id=pi.id AND prr.status='COMPLETED'),0) returned_quantity FROM purchase_items pi JOIN products pr ON pr.id=pi.product_id AND pr.business_id=pi.business_id JOIN units_of_measure tu ON tu.id=pi.purchase_uom_id LEFT JOIN units_of_measure ppu ON ppu.id=pr.package_uom_id LEFT JOIN product_batches pb ON pb.id=pi.batch_id AND pb.business_id=pi.business_id WHERE pi.purchase_id=? AND pi.business_id=? ORDER BY pi.id");
    mysqli_stmt_bind_param($detailLineStmt,'ii',$viewId,$businessId);mysqli_stmt_execute($detailLineStmt);$detailResult=mysqli_stmt_get_result($detailLineStmt);while($line=mysqli_fetch_assoc($detailResult))$detailLines[]=$line;
    $detailPaymentStmt=mysqli_prepare($conn,"SELECT pp.*,CONCAT(u.first_name,' ',u.last_name) recorded_by FROM purchase_payments pp LEFT JOIN business_memberships bm ON bm.id=pp.recorded_by_membership_id AND bm.business_id=pp.business_id LEFT JOIN users u ON u.id=bm.user_id WHERE pp.purchase_id=? AND pp.business_id=? ORDER BY pp.paid_at,pp.id");
    mysqli_stmt_bind_param($detailPaymentStmt,'ii',$viewId,$businessId);mysqli_stmt_execute($detailPaymentStmt);$detailPaymentResult=mysqli_stmt_get_result($detailPaymentStmt);while($payment=mysqli_fetch_assoc($detailPaymentResult))$detailPayments[]=$payment;
    $detailReturnStmt=mysqli_prepare($conn,"SELECT pr.return_number,pr.return_date,pr.reason,pr.status,pr.created_at,pri.quantity,pri.unit_cost,pri.line_total,p.name product_name,p.sku,p.uom,pb.lot_number,CONCAT(u.first_name,' ',u.last_name) created_by FROM purchase_returns pr JOIN purchase_return_items pri ON pri.purchase_return_id=pr.id AND pri.business_id=pr.business_id JOIN products p ON p.id=pri.product_id AND p.business_id=pri.business_id LEFT JOIN product_batches pb ON pb.id=pri.batch_id AND pb.business_id=pri.business_id LEFT JOIN business_memberships bm ON bm.id=pr.created_by_membership_id AND bm.business_id=pr.business_id LEFT JOIN users u ON u.id=bm.user_id WHERE pr.purchase_id=? AND pr.business_id=? ORDER BY pr.return_date DESC,pr.id DESC,pri.id");
    mysqli_stmt_bind_param($detailReturnStmt,'ii',$viewId,$businessId);mysqli_stmt_execute($detailReturnStmt);$detailReturnResult=mysqli_stmt_get_result($detailReturnStmt);while($returnLine=mysqli_fetch_assoc($detailReturnResult))$detailReturns[]=$returnLine;
  }
}
?>
<?php if($detailPurchase):$meta=$statusMeta($detailPurchase['status']);$detailReceived=0.0;$detailRemaining=0.0;$detailReturned=0.0;$detailOrderedQty=0.0;$detailReceivedQty=0.0;foreach($detailLines as $line){$detailReceived+=(float)$line['received_quantity']*(float)$line['unit_cost'];$detailRemaining+=max(0,(float)$line['ordered_quantity']-(float)$line['received_quantity'])*(float)$line['unit_cost'];$detailReturned+=(float)$line['returned_quantity']*(float)$line['unit_cost'];$detailOrderedQty+=(float)$line['ordered_quantity'];$detailReceivedQty+=(float)$line['received_quantity'];}$detailProgress=$detailOrderedQty>0?min(100,($detailReceivedQty/$detailOrderedQty)*100):0;$detailBalance=max(0,(float)$detailPurchase['total_amount']-(float)$detailPurchase['amount_paid']);?>
<div class="modal-overlay purchase-details-overlay" style="display:flex" id="purchaseDetailsModal"><div class="modal-content-card details-modal-card" role="dialog" aria-modal="true" aria-labelledby="purchaseDetailsTitle"><div class="modal-header purchase-details-header"><div><div class="modal-title" id="purchaseDetailsTitle">Purchase Details</div><p>A complete record of order, receiving, payment, and return activity.</p></div><a class="modal-close-btn" href="index<?php echo $closeQuery?'?'.e($closeQuery):'';?>" aria-label="Close purchase details">&times;</a></div>
<div class="details-hero"><div><span>Purchase order</span><strong><?php echo e($detailPurchase['purchase_number']);?></strong><small><?php echo e($detailPurchase['supplier_name']);?> &middot; <?php echo e(formatDate($detailPurchase['purchase_date'],$config['timezone'],'d M Y, H:i'));?></small></div><div class="details-hero-status"><span class="status-pill <?php echo $meta[1];?>"><?php echo e($meta[0]);?></span><small><?php echo e(number_format($detailProgress,1));?>% received</small></div></div>
<div class="modal-body details-body">
  <section class="purchase-detail-section"><div class="purchase-detail-heading"><div><strong>Order overview</strong></div><small>Supplier, delivery, dates, and workflow</small></div><div class="purchase-overview-grid">
    <article class="purchase-detail-card"><h4>Supplier</h4><dl><div><dt>Name</dt><dd><?php echo e($detailPurchase['supplier_name']);?></dd></div><div><dt>Supplier code</dt><dd><?php echo e($detailPurchase['supplier_code']);?></dd></div><div><dt>Contact person</dt><dd><?php echo e($detailPurchase['supplier_contact']?:'Not recorded');?></dd></div><div><dt>Phone</dt><dd><?php echo e($detailPurchase['supplier_phone']?:'Not recorded');?></dd></div><div><dt>Email</dt><dd><?php echo e($detailPurchase['supplier_email']?:'Not recorded');?></dd></div><div><dt>Tax number</dt><dd><?php echo e($detailPurchase['supplier_tax_number']?:'Not recorded');?></dd></div><div class="detail-wide"><dt>Address</dt><dd><?php echo e($detailPurchase['supplier_address']?:'Not recorded');?></dd></div></dl></article>
    <article class="purchase-detail-card"><h4>Order &amp; delivery</h4><dl><div><dt>Supplier invoice</dt><dd><?php echo e($detailPurchase['supplier_invoice_number']?:'Not recorded');?></dd></div><div><dt>Location</dt><dd><?php echo e($detailPurchase['location_name'].' ('.$detailPurchase['location_code'].')');?></dd></div><div><dt>Location type</dt><dd><?php echo e(ucwords(strtolower($detailPurchase['location_type'])));?></dd></div><div><dt>Expected date</dt><dd><?php echo $detailPurchase['expected_date']?e(date('d M Y',strtotime($detailPurchase['expected_date']))):'Not specified';?></dd></div><div><dt>Received at</dt><dd><?php echo $detailPurchase['received_at']?e(formatDate($detailPurchase['received_at'],$config['timezone'],'d M Y, H:i')):'Not completed';?></dd></div><div class="detail-wide"><dt>Delivery address</dt><dd><?php echo e($detailPurchase['location_address']?:'Not recorded');?></dd></div></dl></article>
    <article class="purchase-detail-card"><h4>Workflow</h4><dl><div><dt>Created by</dt><dd><?php echo e(trim((string)$detailPurchase['created_by'])?:'System');?></dd></div><div><dt>Approved by</dt><dd><?php echo e(trim((string)$detailPurchase['approved_by'])?:'Not approved');?></dd></div><div><dt>Received by</dt><dd><?php echo e(trim((string)$detailPurchase['received_by'])?:'Not received');?></dd></div><div><dt>Created</dt><dd><?php echo e(formatDate($detailPurchase['created_at'],$config['timezone'],'d M Y, H:i'));?></dd></div><div><dt>Last updated</dt><dd><?php echo e(formatDate($detailPurchase['updated_at'],$config['timezone'],'d M Y, H:i'));?></dd></div><div><dt>Product lines</dt><dd><?php echo count($detailLines);?></dd></div></dl></article>
  </div></section>
  <section class="purchase-detail-section"><div class="purchase-detail-heading"><div><strong>Financial summary</strong></div><small>Order value and settlement</small></div><div class="detail-value-grid financial-value-grid"><div><span>Subtotal</span><strong><?php echo formatCurrency($detailPurchase['subtotal'],$currency);?></strong></div><div><span>Discount</span><strong><?php echo formatCurrency($detailPurchase['discount_amount'],$currency);?></strong></div><div><span>Tax</span><strong><?php echo formatCurrency($detailPurchase['tax_amount'],$currency);?></strong></div><div><span>Shipping</span><strong><?php echo formatCurrency($detailPurchase['shipping_amount'],$currency);?></strong></div><div class="value-total"><span>Order total</span><strong><?php echo formatCurrency($detailPurchase['total_amount'],$currency);?></strong></div><div><span>Amount paid</span><strong class="received-text"><?php echo formatCurrency($detailPurchase['amount_paid'],$currency);?></strong></div><div><span>Balance due</span><strong class="remaining-text"><?php echo formatCurrency($detailBalance,$currency);?></strong></div><div><span>Returned value</span><strong><?php echo formatCurrency($detailReturned,$currency);?></strong></div></div></section>
  <section class="purchase-detail-section"><div class="purchase-detail-heading"><div><strong>Purchased items</strong></div><small>Products, registered purchase forms, receiving, batches, and pricing</small></div><div class="receipt-progress"><div><span style="width:<?php echo e(number_format($detailProgress,2,'.',''));?>%"></span></div><small><?php echo e(number_format($detailProgress,1));?>% received &middot; <?php echo formatCurrency($detailReceived,$currency);?> received &middot; <?php echo formatCurrency($detailRemaining,$currency);?> pending</small></div><div class="details-lines-wrap"><table class="data-table details-lines purchase-detail-lines"><thead><tr><th>Product</th><th>Batch / Expiry</th><th>Ordered</th><th>Received</th><th>Returned</th><th>Pending</th><th>Purchase Price</th><th>Sales Amount</th><th>Discount</th><th>Tax</th><th>Line Total</th></tr></thead><tbody><?php foreach($detailLines as $line):$factor=(float)$line['conversion_factor_to_base'];$remaining=max(0,(float)$line['ordered_quantity']-(float)$line['received_quantity']);$receivedEntered=convertBaseQuantityToTransaction($line['received_quantity'],$factor);$returnedEntered=convertBaseQuantityToTransaction($line['returned_quantity'],$factor);$remainingEntered=convertBaseQuantityToTransaction($remaining,$factor);?><tr><td><strong><?php echo e($line['product_name']);?></strong><small>SKU: <?php echo e($line['sku']);?><?php if($line['barcode']):?> &middot; Barcode: <?php echo e($line['barcode']);?><?php endif;?></small></td><td><?php echo e($line['lot_number']?:'No batch');?><?php if($line['expires_at']):?><small>Expires <?php echo e(date('d M Y',strtotime($line['expires_at'])));?></small><?php endif;?></td><td><?php echo formatInventoryDecimal($line['purchase_quantity']);?> <small><?php echo e($line['purchase_uom']);?> &middot; <?php echo formatInventoryDecimal($line['ordered_quantity']).' '.e($line['uom']);?> base</small></td><td class="received-text"><?php echo formatInventoryDecimal($receivedEntered);?> <small><?php echo e($line['purchase_uom']);?></small></td><td><?php echo formatInventoryDecimal($returnedEntered);?> <small><?php echo e($line['purchase_uom']);?></small></td><td class="remaining-text"><?php echo formatInventoryDecimal($remainingEntered);?> <small><?php echo e($line['purchase_uom']);?></small></td><td><?php echo formatCurrency($line['purchase_unit_cost'],$currency);?> <small>/ <?php echo e($line['purchase_uom']);?> &middot; <?php echo formatCurrency($line['unit_cost'],$currency);?> / <?php echo e($line['uom']);?></small></td><td><?php echo formatCurrency($line['unit_selling_price'],$currency);?> <small>/ <?php echo e($line['uom']);?><?php if($line['package_selling_price']!==null&&$line['package_uom']):?> &middot; <?php echo formatCurrency($line['package_selling_price'],$currency);?> / <?php echo e($line['package_uom']);?><?php endif;?></small></td><td><?php echo formatCurrency($line['discount_amount'],$currency);?></td><td><?php echo formatCurrency($line['tax_amount'],$currency);?></td><td class="td-bold"><?php echo formatCurrency($line['line_total'],$currency);?></td></tr><?php endforeach;?></tbody></table></div></section>
  <div class="purchase-detail-columns">
    <section class="purchase-detail-section"><div class="purchase-detail-heading"><div><strong>Payments</strong></div><small><?php echo count($detailPayments);?> record(s)</small></div><?php if(!$detailPayments):?><div class="purchase-detail-empty">No payments have been recorded for this purchase.</div><?php else:?><div class="detail-record-list"><?php foreach($detailPayments as $payment):?><article><div><strong><?php echo e(ucwords(strtolower(str_replace('_',' ',$payment['payment_method']))));?></strong><small><?php echo e(formatDate($payment['paid_at'],$config['timezone'],'d M Y, H:i'));?> &middot; <?php echo e(trim((string)$payment['recorded_by'])?:'System');?></small></div><b><?php echo formatCurrency($payment['amount'],$currency);?></b><p>Reference: <?php echo e($payment['reference_number']?:'Not recorded');?><?php if($payment['notes']):?> &middot; <?php echo e($payment['notes']);?><?php endif;?></p></article><?php endforeach;?></div><?php endif;?></section>
    <section class="purchase-detail-section"><div class="purchase-detail-heading"><div><strong>Returns</strong></div><small><?php echo count($detailReturns);?> line(s)</small></div><?php if(!$detailReturns):?><div class="purchase-detail-empty">No stock has been returned against this purchase.</div><?php else:?><div class="detail-record-list"><?php foreach($detailReturns as $returnLine):?><article><div><strong><?php echo e($returnLine['return_number'].' · '.$returnLine['product_name']);?></strong><small><?php echo e(formatDate($returnLine['return_date'],$config['timezone'],'d M Y, H:i'));?> &middot; <?php echo number_format($returnLine['quantity'],4).' '.e($returnLine['uom']);?></small></div><b><?php echo formatCurrency($returnLine['line_total'],$currency);?></b><p><?php echo e($returnLine['reason']?:'No return reason');?> &middot; Recorded by <?php echo e(trim((string)$returnLine['created_by'])?:'System');?></p></article><?php endforeach;?></div><?php endif;?></section>
  </div>
  <section class="purchase-detail-section purchase-notes-section"><div class="purchase-detail-heading"><div><strong>Notes</strong></div></div><div class="purchase-notes-grid"><div><span>Purchase notes / instructions</span><p><?php echo nl2br(e($detailPurchase['notes']?:'No purchase notes were recorded.'));?></p></div><div><span>Supplier notes</span><p><?php echo nl2br(e($detailPurchase['supplier_notes']?:'No supplier notes were recorded.'));?></p></div></div></section>
</div>
<div class="modal-footer purchase-details-footer"><div><span>Order total</span><strong><?php echo formatCurrency($detailPurchase['total_amount'],$currency);?></strong></div><div><a class="btn-sm" href="index<?php echo $closeQuery?'?'.e($closeQuery):'';?>">Close</a><?php if(in_array($detailPurchase['status'],['ORDERED','PARTIALLY_RECEIVED'],true)&&$canReceivePurchase):?><a class="btn-primary details-receive" href="../receiving/view?id=<?php echo (int)$detailPurchase['id'];?><?php echo getPreviewRole()?'&role='.e(getPreviewRole()):'';?>">Open Receiving</a><?php endif;?></div></div></div></div>
<?php endif;?>

<?php
$returnPurchase=null;$returnLines=[];$returnId=(int)($_GET['return_id']??0);$returnFromView=($_GET['return_to']??'')==='view';
$returnCloseUrl=$returnFromView&&$returnId>0?'view?id='.$returnId.($roleQuery!==''?'&role='.rawurlencode((string)getPreviewRole()):''):'index'.($closeQuery?'?'.$closeQuery:'');
if($canReceivePurchase&&$returnId>0){$returnStmt=mysqli_prepare($conn,"SELECT id,purchase_number,status FROM purchases WHERE id=? AND business_id=? AND status IN ('PARTIALLY_RECEIVED','RECEIVED')");mysqli_stmt_bind_param($returnStmt,'ii',$returnId,$businessId);mysqli_stmt_execute($returnStmt);$returnPurchase=mysqli_fetch_assoc(mysqli_stmt_get_result($returnStmt));if($returnPurchase){$returnLineStmt=mysqli_prepare($conn,"SELECT pi.id,pi.purchase_uom_id,pi.conversion_factor_to_base,pi.received_quantity,pi.unit_cost,p.name,p.sku,p.uom,tu.code purchase_uom,pb.lot_number,COALESCE((SELECT SUM(pri.quantity) FROM purchase_return_items pri JOIN purchase_returns pr ON pr.id=pri.purchase_return_id WHERE pri.purchase_item_id=pi.id AND pr.status='COMPLETED'),0) returned_quantity FROM purchase_items pi JOIN products p ON p.id=pi.product_id AND p.business_id=pi.business_id JOIN units_of_measure tu ON tu.id=pi.purchase_uom_id LEFT JOIN product_batches pb ON pb.id=pi.batch_id AND pb.business_id=pi.business_id WHERE pi.purchase_id=? AND pi.business_id=? AND pi.received_quantity>0 ORDER BY pi.id");mysqli_stmt_bind_param($returnLineStmt,'ii',$returnId,$businessId);mysqli_stmt_execute($returnLineStmt);$rr=mysqli_stmt_get_result($returnLineStmt);while($line=mysqli_fetch_assoc($rr))$returnLines[]=$line;}}
?>
<?php if($returnPurchase):?><div class="modal-overlay" style="display:flex"><div class="modal-content-card return-modal-card"><div class="modal-header"><div><div class="modal-title">Return Purchase Stock</div><p><?php echo e($returnPurchase['purchase_number']);?> &middot; return previously received quantities</p></div><a class="modal-close-btn" href="index<?php echo $closeQuery?'?'.e($closeQuery):'';?>">&times;</a></div><form action="backend<?php echo e($roleQuery);?>" method="POST"><div class="modal-body"><input type="hidden" name="csrf_token" value="<?php echo e($csrfToken);?>"><input type="hidden" name="idempotency_key" value="<?php echo e(createIdempotencyToken());?>"><input type="hidden" name="action" value="return_purchase"><input type="hidden" name="purchase_id" value="<?php echo $returnId;?>"><div class="return-info-grid"><label>Return Number<input name="return_number" value="PRET-<?php echo e($localNow->format('YmdHis'));?>" required></label><label>Return Date<input type="datetime-local" name="return_date" value="<?php echo e($localNow->format('Y-m-d\TH:i'));?>" required></label></div><div class="details-lines-wrap"><table class="data-table return-lines"><thead><tr><th>Product</th><th>Received</th><th>Already Returned</th><th>Available</th><th>Return Now</th><th>Base Cost</th></tr></thead><tbody><?php foreach($returnLines as $line):$returnable=max(0,(float)$line['received_quantity']-(float)$line['returned_quantity']);$factor=(float)$line['conversion_factor_to_base'];$returnableEntered=convertBaseQuantityToTransaction($returnable,$factor);?><tr><td><strong><?php echo e($line['name']);?></strong><small><?php echo e($line['sku']);?></small></td><td><?php echo formatInventoryDecimal(convertBaseQuantityToTransaction($line['received_quantity'],$factor));?> <?php echo e($line['purchase_uom']);?></td><td><?php echo formatInventoryDecimal(convertBaseQuantityToTransaction($line['returned_quantity'],$factor));?> <?php echo e($line['purchase_uom']);?></td><td><?php echo formatInventoryDecimal($returnableEntered);?> <?php echo e($line['purchase_uom']);?></td><td><input type="hidden" name="item_ids[]" value="<?php echo (int)$line['id'];?>"><input type="number" name="return_quantities[]" min="0" max="<?php echo e(number_format($returnableEntered,4,'.',''));?>" step=".0001" value="0" <?php echo $returnable<=0?'readonly':'';?>></td><td><?php echo formatCurrency($line['unit_cost'],$currency);?> / <?php echo e($line['uom']);?></td></tr><?php endforeach;?></tbody></table></div><label class="return-reason">Reason<textarea name="reason" rows="3" required></textarea></label></div><div class="modal-footer"><a class="btn-sm" href="index<?php echo $closeQuery?'?'.e($closeQuery):'';?>">Cancel</a><button class="btn-primary">Complete Purchase Return</button></div></form></div></div><?php endif;?>
<?php if($returnPurchase&&$returnFromView):?><script>(function(){var modal=document.querySelector('.return-modal-card');if(!modal)return;var form=modal.querySelector('form');var input=document.createElement('input');input.type='hidden';input.name='return_to';input.value=<?php echo json_encode('purchase_view:'.$returnId);?>;form.appendChild(input);modal.querySelectorAll('.modal-close-btn,.modal-footer a').forEach(function(link){link.href=<?php echo json_encode($returnCloseUrl);?>;});var cancel=modal.querySelector('.modal-footer a');if(cancel)cancel.textContent='Cancel Return';})();</script><?php endif;?>

